changeSet.sql:
UPDATE services SET title_fr = 'VTC & Livraison' WHERE title_fr = 'Mobilité, VTC & Livraison';
UPDATE services SET title_en = 'Ride-hailing & Delivery' WHERE title_en IN ('Mobility, Ride-hailing & Delivery', 'Mobility, ride-hailing & delivery');
UPDATE services SET short_title_fr = 'VTC & Livraison' WHERE short_title_fr = 'Mobilité';
UPDATE services SET short_title_en = 'Ride-hailing & Delivery' WHERE short_title_en = 'Mobility';

UPDATE about_workforce_tabs SET title_fr = 'Construction' WHERE title_fr = 'Construction & rénovation';
UPDATE about_workforce_tabs SET title_en = 'Construction' WHERE title_en IN ('Construction & renovation', 'Construction & Renovation');
UPDATE about_workforce_tabs SET title_fr = 'VTC & Livraison' WHERE title_fr = 'Mobilité, VTC & Livraison';
UPDATE about_workforce_tabs SET title_en = 'Ride-hailing & Delivery' WHERE title_en IN ('Mobility, ride-hailing & delivery', 'Mobility, Ride-hailing & Delivery');

UPDATE site_contact SET footer_about_fr = 'Africa Talent Habitat & Logistique — construction, VTC & livraison et importation de matériaux, portées par des équipes qualifiées.'
    WHERE footer_about_fr = 'Africa Talent Habitat & Logistique — construction, rénovation, mobilité et importation de matériaux, portées par des équipes qualifiées.';
UPDATE site_contact SET footer_about_en = 'Africa Talent Habitat & Logistics — construction, ride-hailing & delivery and import of materials, delivered by skilled teams.'
    WHERE footer_about_en = 'Africa Talent Habitat & Logistics — construction, renovation, mobility and import of materials, delivered by skilled teams.';

UPDATE page_headers SET subtitle_fr = 'Chantiers livrés, nouveaux partenariats, recrutements : les dernières nouvelles de nos équipes construction, VTC & livraison et import-logistique.'
    WHERE page_key = 'news' AND subtitle_fr = 'Chantiers livrés, nouveaux partenariats, recrutements : les dernières nouvelles de nos équipes BTP, mobilité et import-logistique.';
UPDATE page_headers SET subtitle_en = 'Completed sites, new partnerships, hiring campaigns: the latest updates from our construction, ride-hailing & delivery and import-logistics teams.'
    WHERE page_key = 'news' AND subtitle_en = 'Completed sites, new partnerships, hiring campaigns: the latest updates from our construction, mobility and import-logistics teams.';
UPDATE page_headers SET subtitle_fr = 'Construction, VTC & livraison, import & logistique : un aperçu de nos projets livrés et en cours, par métier.'
    WHERE page_key = 'projects' AND subtitle_fr = 'Construction, import & logistique, mobilité : un aperçu de nos projets livrés et en cours, par métier.';
UPDATE page_headers SET subtitle_en = 'Construction, ride-hailing & delivery, import & logistics: a look at our delivered and ongoing projects, by business line.'
    WHERE page_key = 'projects' AND subtitle_en = 'Construction, import & logistics, mobility: a look at our delivered and ongoing projects, by business line.';
